window.DATA=[{"n":1,"title":"Introduction to Node.js REPL","page":1,"pages":[{"p":1,"t":"Introduction To Node.js Repl","i":[]}]},{"n":2,"title":"Creating JavaScript Files in Node.js","page":2,"pages":[{"p":2,"t":"Creating JavaScript Files in Node.js","i":[]}]},{"n":3,"title":"Creating a Node.js Project using npm","page":3,"pages":[{"p":3,"t":"Creating a Node.js Project using npm","i":[]}]},{"n":4,"title":"Creating a Basic HTTP Server using Node.js","page":4,"pages":[{"p":4,"t":"Creating a Basic HTTP Server using Node.js\n\n\n\n\nserver1.js\nconst http=require(\"http\");\nconst server=http.createServer((req,res)=>\n{res.write(\"Hello...my Server is running\");\nres.end();\n});\n\nserver.listen(3000,()=>{\nconsole.log(\"Server is running on http://localhost:3000\")\n});","i":[]},{"p":5,"t":"Adding routes to server\nconst http=require(\"http\");\nconst server=http.createServer((req,res)=>\n{if(req.url===\"/\")\n{res.write(\"Homepage\");}\n\nelse if(req.url===\"/about\")\n{res.write(\"About Page\");}\n\nelse if(req.url===\"/contact\")\n{res.write(\"Contact Page);}\n\nelse{res.write(\"404-Page Not Found\");}\nres.end();\n});\n\nserver.listen(3000,()=>{\nconsole.log(\"Server is running on http://localhost:3000\")\n});","i":[]}]},{"n":5,"title":"Installing and Configuring Express.js","page":6,"pages":[{"p":6,"t":"Installing and Configuring Express.js\n\n\n\n\nconst express=require(\"express\");\nconst app=express();\napp.get(\"/\",(req,res)=>\n{res.send(\"hello express\");\n});\n\napp.listen(3000, ()=>{console.log(\"server is running on\nhttp://localhost:3000\");\n});","i":[]}]},{"n":6,"title":"Express Routing","page":7,"pages":[{"p":7,"t":"Express Routing\nconst express=require(\"express\");\nconst app=express();\napp.get(\"/\",(req,res)=>\n{res.send(\"hello express\");\n});\napp.get(\"/about\",(req,res)=>\n{res.send(\"about page\");\n});\napp.get(\"/contact\",(req,res)=>\n{res.send(\"contact page\");\n});\n\napp.listen(3000, ()=>{console.log(\"server is running on\nhttp://localhost:3000\");\n});","i":[]}]},{"n":7,"title":"User-Defined Modules","page":8,"pages":[{"p":8,"t":"User-Defined Modules\n  1.   Creating user defined module to take names and display the full name\n       Mod1.js\n       function displayName(fName, lName)\n       {console.log(\"Fullname:\" +fName+\" \"+lName);}\n       module.exports=displayName;\n\n       app1.js\n       const displayName=require('./mod1');\n       displayName(\"Samantha\", \"Fernandez\");\n\n\n\n\n  2. Create a user defined module to add and subtract\n  Calcy.js\n  function add(a,b)\n  {return a+b;}\n     function sub(a,b)\n     {return a-b;}\n     module.exports={add,sub};\n\n       app2.js\n       const cal=require('./calcy');\n       console.log(\"addition:\" +cal.add(10,20));\n       console.log(\"subtraction:\" +cal.sub(30,20));","i":[]},{"p":9,"t":"3. Create an area calculator\nareaCalculator1.js\nfunction circleArea(radius)\n{return 3.14*radius*radius;}\n\nfunction rectangleArea(length, breadth)\n{return length*breadth;}\n\nfunction triangleArea(base, height)\n{return 0.5*base*height;}\n\nmodule.exports= {circleArea, rectangleArea, triangleArea};\n\napp3.js\nconst area= require('./areaCalculator1.js');\nconsole.log(\"Area of circle:\" +area.circleArea(8));\nconsole.log(\"Area of rectangle:\" +area.rectangleArea(8,2));\nconsole.log(\"Area of triangle:\" +area.triangleArea(8,2));","i":[]}]},{"n":8,"title":"Synchronous File Operations using fs Module","page":10,"pages":[{"p":10,"t":"Synchronous File Operations using FS Module\n  1. File System module (WRITE AND READ FROM A FILE)\n  const fs= require(\"fs\");\n  fs.writeFileSync(\"sample.txt\", \"welcome to node.js\");\n  let data = fs.readFileSync(\"sample.txt\", \"utf8\");\n  console.log(data);\n\n\n\n\n  2. File System Module (Append)\n  const fs= require(\"fs\");\n  fs.writeFileSync(\"sample.txt\", \"welcome to node.js\");\n  let data = fs.readFileSync(\"sample.txt\", \"utf8\");\n  fs.appendFileSync(\"sample.txt\", \"\\n this is a new appended line\");\n  let updateddata = fs.readFileSync(\"sample.txt\", \"utf8\");\n  console.log(updateddata);\n\n\n\n\n  3. File System Module (Delete)\n  fs.unlinkSync(\"sample.txt\");\n  console.log(\"file deleted successfully\");","i":[]}]},{"n":9,"title":"File Operations using fs and path Modules","page":11,"pages":[{"p":11,"t":"File Operations using FS and Path Modules\nconst path=require(\"path\");\nconst fs=require(\"fs\");\nconst filepath=path.join(__dirname, 'data', 'sample.txt');\nfs.writeFileSync(filepath, \"this is a sample file\"); //write to file\nconst fileContent = fs.readFileSync(filepath, 'utf8'); //reading file\nconsole.log(fileContent);","i":[]}]},{"n":10,"title":"Colors Module","page":12,"pages":[{"p":12,"t":"Colors Module\nconst colors= require(\"colors\");\nconsole.log(\"WELCOME TO NODE JS\".purple);\nconsole.log(\"Error occured\".red);\nconsole.log(\"this is a rainbow\".rainbow.bold);\nconsole.log(\"i can underline this :) \".blue.underline);\nconsole.log(\"Express\".italic.bgYellow);\n\ncolors.disable(); //disables the module\n\nconsole.log(\"this is a rainbow\".rainbow.bold);\n\nconsole.enable(); //enables the module\n\nconsole.log(\"WELCOME TO NODE JS\".purple);\nconsole.log(\"Error occured\".red);","i":[]}]},{"n":11,"title":"Serving HTML Pages using res.sendFile()","page":13,"pages":[{"p":13,"t":"Serving HTML Pages using res.sendFile()\ndashboard.html\n<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <title>Dashboard using Express</title>\n    </head>\n    <body>\n        <h1>Dashboard</h1>\n        <p>Hello Server</p>\n        <h2>This is a dashboard created under views folder and called\nfrom index.js</h2>\n    </body>\n</html>\n\nindex.js\nconst express=require(\"express\");\nconst app=express();\n\nconst path=require(\"path\");\napp.get('/dashboard',(req, res)=>\n    {\n    res.sendFile(path.join(__dirname,'views', 'dashboard.html'));\n    });\n\nconst port=3000;\napp.listen(port,()=>\n{\n    console.log(\"Server is running on\nhttp://localhost:3000/dashboard\");\n})","i":[]}]},{"n":12,"title":"Serving Static Files using Express","page":14,"pages":[{"p":14,"t":"Serving Static Files using Express\naboutus.html\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-\nscale=1.0\">\n    <title>About Us</title>\n    <link rel=\"stylesheet\"href=\"style.css\">\n    <script src =\"script.js\"></script>\n</head>\n<body>\n    <h1>About Us</h1>\n    <p>Hello everybody welcome to our page</p>\n    <img src=\"21.jpeg\"> <br><br>\n         <button onclick=\"showmessage()\">submit</button>\n</body>\n</html>\n\nindex1.js\nconst express=require(\"express\");\nconst app=express();\n\nconst path=require(\"path\");\napp.get('/aboutus',(req, res)=>\n    {\n    res.sendFile(path.join(__dirname,'views', 'aboutus.html'));\n    });\n\napp.use(express.static(path.join(__dirname, 'public')));\n\nconst port=3000;\napp.listen(port,()=>\n{\n    console.log(\"Server is running on http://localhost:3000/aboutus\");\n})","i":[]},{"p":15,"t":"script.js\nfunction showMessage()\n{\n    alert(\"Welcome to about page:) \");\n}\n\nstyle.css\nbody{\n    background-color: coral;\n}\n\nh1{\n      color:antiquewhite;\n}\n\np{\n      font-size: 30px;\n}","i":[]}]},{"n":13,"title":"Asynchronous Programming","page":16,"pages":[{"p":16,"t":"Asynchronous Programming\n\n  1.   Callback\n       function processUser(user)\n       {\n            let username=\"Samantha\";\n            user(username);\n\n       }\n\n       processUser(greet); //user==greet\n\n       function greet(name)\n       {\n\n           console.log(\"hello \"+name);\n\n       }\n\n\n\n\n  2. Set timeout\n     function display()\n     {\n           console.log(\"Hello after 5 seconds\");\n\n       }\n\n       console.log(\"start\");\n       setTimeout(display,5000);\n       console.log(\"end\");","i":[]},{"p":17,"t":"3. Set interval\n   console.log(\"program started\");\n   function display()\n   {\n        console.log(\"hi this is in 2 seconds\")\n   }\n   const interval=setInterval(display,2000); //displays message\n   every 2 seconds\n   setTimeout(()=>{\n        clearInterval(interval);\n        console.log(\"program is stopped\");}, 10000); //stops the\n   interval at 10 seconds\n   console.log(\"program is running\");","i":[]},{"p":18,"t":"4. Performing file operations asynchronously\n         const fs=require(\"fs\");\n   const path=require(\"path\");\n   const filepath=path.join(__dirname, \"data\", \"stddata.txt\");\n   const details= `name: samantha\n   roll no: 37`;\n   console.log(\"before write file function call\");\n  //write\n  fs.writeFile(filepath, details, function(err)\n  {\n       if(err)\n       {\n             console.log(\"error occurred\",+err);\n       }\n       else{\n             console.log(\"file written successfully\");\n             //read file\n       fs.readFile(filepath, \"utf8\",function(err,data)\n       {\n             if(err)\n             {\n                  console.log(\"error while reading the file\")\n             }\n        else{\n                console.log(data)\n  //append\n                  const details2=\"\\nclass: TYBCA\";\n                fs.appendFile(filepath,details2,function(err)\n                {\n                       if(err)\n                       {\n                  console.log(\"cannot append\");\n                  }\n                       else{console.log(\"data appended\");\n                    fs.readFile(filepath, \"utf8\",function(err,data)\n        {\n                if(err)\n        {\n                  console.log(\"error while reading the file\")\n                }\n                 else{\n                  console.log(data);\n                  fs.unlink(filepath, function(err)\n                  {\n                      if(err)\n                      {\n                          console.log(\"error while deleting\");\n                      }\n                      else\n                      {","i":[]},{"p":19,"t":"                       console.log(\"deleted\");\n                   }});\n            }});\n        }});\n    }});\n}});\n\n   console.log(\"after read function\");","i":[]}]},{"n":14,"title":"Callback Functions","page":20,"pages":[{"p":20,"t":"Callback Functions\nfunction greet()\n{\n    console.log(\"welcome to the page\");\n    greet();\n}\n\nfunction sum(a,b)\n{\n    let add=a+b;\n    return add;\n}\n\nlet result=sum(12,23);\nconsole.log(\"addition:\",result);\n\nfunction fullname()\n{\n    console.log(\"hello my name is Samantha\");\n    stddetails;\n}\n\nfunction stddetails()\n{\n    let details= `roll no: 123\n        class: TYBCA\n        subject opted: fs,ui ux`;\n        console.log(details);\n}\n\nfullname();","i":[]},{"p":21,"t":"function multiply(a,b,callback)\n{\n    let multi=a*b;\n    callback(multi)\n}\n\nfunction display(result)\n{\n    console.log(\"multiplication:\", result);\n}\n\nmultiply(6,7,display);","i":[]}]},{"n":15,"title":"Event Emitters","page":22,"pages":[{"p":22,"t":"Event Emitters\n  1.   Simple event emitter\n       const eventEmitter=require(\"events\");\n\n       const events=new eventEmitter();\n\n       events.on(\"greet\", ()=> //events.on is the listener which allows\n       processing\n       {\n           console.log(\"hello everybody\");\n       });\n\n       events.emit(\"greet\"); //emits triggers the greet event\n\n\n\n  2. Event emitter (passing arguments)\n     const eventEmitter=require(\"events\");\n\n       const events=new eventEmitter();\n\n       events.on(\"welcome\", (name)=> //events.on is the listener which\n       allows processing\n       {\n           console.log(\"welcome \" +name);\n       });\n       events.emit(\"welcome\", \"samantha\"); //emits triggers the greet\n       event","i":[]},{"p":23,"t":"3. Same event name, different callbacks\n   const eventEmitter=require(\"events\");\n\n   const events=new eventEmitter();\n\n   events.on(\"student\", (rollno)=>\n   {\n       console.log(\"Roll No:\" + rollno);\n   });\n   events.on(\"student\", (rollno,name)=>\n   {\n       console.log(\"\\nrollno: \" +rollno);\n       console.log(\"\\nName: \"+name);\n   });\n   events.emit(\"student\", 37, \"samantha\");\n\n\n\n\n4. Event.once\n\n   const eventEmitter=require(\"events\");\n\n   const events=new eventEmitter();\n\n   events.once(\"warning\", ()=>\n   {\n       console.log(\"your data pack is over\");\n   })\n\n   events.emit(\"warning\");\n   events.emit(\"warning\");","i":[]},{"p":24,"t":"5. Removing event emitters\n   const eventEmitter=require(\"events\");\n   const events=new eventEmitter();\n   function display()\n   {\n       console.log(\"connection established\");\n   }\n   events.on(\"connection\", display);\n   events.emit(\"connection\");\n   events.off(\"connection\", display); //turns of the event\n   events.emit(\"connection\");","i":[]},{"p":25,"t":"Practice codes:\n   1. Create a node.js app to track students progress. Emit three events:\n   • Start - display “hello <name>! Lets begin learning”\n   • Progress - display “you have completed <percentage>% of course”\n   • Complete - display “congratulations you have completed the course”\n       const eventEmitter=require(\"events\");\n   const events=new eventEmitter();\n   events.on(\"start\", (name)=>\n   {\n         console.log(\"Hello \" +name+ \"! \" +\"Let's begin learning\");\n   });\n   events.emit(\"start\", \"Samantha\");\n   events.on(\"progress\", (percentage)=>\n   {\n   console.log(\"You have completed \" +percentage+ \"% \"\n   +\"of         course\");\n   });\n   events.emit(\"progress\", 25);\n   events.emit(\"progress\", 50);\n   events.emit(\"progress\", 75);\n   events.emit(\"progress\", 100);\n\n   events.on(\"complete\" ,()=>\n   {\n           console.log(\"Congratulations! You have completed the\n   course\");\n   });\n   events.emit(\"complete\");","i":[]},{"p":26,"t":"2.     Create a user defined module named arrayUtil.js that contains the following\nfunctions\n   • getSum(arr) : calculates and returns the sum of all elements\n   • getAvg(arr): calculates the average of elements in the array\n   • getMax(arr): gives the maximum value in the array\n       arrayUtil.js\n       function getsum(arr){\n         var sum = 0;\n\n     for (let i = 0; i < arr.length; i++) {\n         sum += arr[i];\n      }\n\n        return sum;\n}\nfunction getavg(arr){\n    if (arr.length==0)\n        {\n            return 0;\n        }\n     return getsum(arr)/arr.length;\n}\n\nfunction getmax(arr){\n     if (arr.length==0)\n        {\n            return 0;\n        }\n     var max=arr[0];\n     for(let i=1; i < arr.length; i++)\n        {\n        if (arr[i]>max)\n            {\n            max=arr[i]\n            }\n     }\nreturn max;\n\n}\nmodule.exports={getsum, getmax, getavg}\n\nindex.js\nconst arrayUtil = require(\"./controller/arrayUtil.js\")","i":[]},{"p":27,"t":"const numbers =[45,67,89,100,12,56];\n\nconsole.log(\"Sum\",arrayUtil.getsum(numbers));\nconsole.log(\"Avg\",arrayUtil.getavg(numbers));\nconsole.log(\"Max\",arrayUtil.getmax(numbers));","i":[]},{"p":28,"t":"3.     Create a user defined module named results.js in controller folder, this module\nshould export functions that accepts the following parameters\nStudentname(), rollnumber(number), fsd(marks), uiux(marks), cc(marks), display total and\naverage.\nresult.js\nfunction stddetails(name,roll,fsd,ui,cc)\n{\n     console.log(\"Name of Student: \"+name);\n     console.log(\"Roll number: \" + roll);\n     console.log(\"FSD MARKS: \" + fsd);\n     console.log(\"UI UX MARKS: \" + ui);\n     console.log(\"CC MARKS: \" + cc);\n     var total= fsd+ui+cc;\n     console.log(\"total marks: \" + total);\n     var avg= total/3;\n     console.log(\"average marks: \" + avg);\n}\n\nmodule.exports={stddetails}\n\nindex.js\nconst result = require(\"./controller/results.js\");\n\nresult.stddetails(\"Samantha\", 2408037, 56,78,90);","i":[]}]},{"n":16,"title":"Exception Handling","page":29,"pages":[{"p":29,"t":"Exception Handling\n  1.   Try Catch\n\n       try{\n           console.log(\"program started\");\n           x=y+10;\n           console.log(x);\n       }\n       catch(err)\n       {\n           console.log(\"error\", err.message);\n       }\n\n\n\n\n  2. Throws\n\n       function chckage(age)\n       {\n           if (age<18)\n           {\n               throw new Error(\"you are not eligible to vote\");\n           }\n\n           console.log(\"you are eligible\");\n       }\n\n       try{\n           chckage(15);\n       }\n       catch(err)\n       {\n           console.log(err.message);\n       }","i":[]},{"p":30,"t":"   3. Finally\n\n      function chckage(age)\n      {\n          if (age<18)\n          {\n              throw new Error(\"you are not eligible to vote\");\n          }\n\n           console.log(\"you are eligible\");\n      }\n\n      try{\n          chckae(15); //theres an error here\n      }\n      catch(err)\n      {\n          console.log(err.message);\n      }\n\n      finally{\n          console.log(\"FINALLY IT OVER!\");\n      }\n\n\n\n\nPractice Codes:\n   1. Create a node.js app containing try catch block to handle exceptions when a\n       variable length is checked for undefined variables.\n       try{\n            let std;\n            console.log(std.length);\n       }\n       catch(err)\n       {\n            console.log(\"Error\", err.message);\n       }","i":[]},{"p":31,"t":"2.    Create a node.js app and throw a divide by zero error\nfunction divide(a,b)\n{\n    if(b===0)\n    {\n         throw new Error(\"Division by Zero\");\n    }\n    else{\n         console.log(a/b);\n    }\n\n}\n\ntry{\n    divide(15,0); //error is here\n}\ncatch(err)\n{\n    console.log(err.message);\n}","i":[]},{"p":32,"t":"3.      Create a node.js application that divides two numbers. Check if the inputs are\nvalid numbers. If either is not throw an exception, if the denominator is zero, throw\ndivision by zero. Otherwise display result.\n\nfunction divide(a,b)\n{\n    if(isNaN(a)||isNaN(b))\n    {\n        throw new Error(\"One is not a number\")\n    }\n    else{\n\n          if(b===0)\n     {\n          throw new Error(\"Division by Zero\");\n     }\n     else{\n         console.log(a/b);\n     }\n\n     }\n\n}\n\ntry{\n    divide(\"s\",\"f\"); //first case\n    divide(55,0; //second case\n}\ncatch(err)\n{\n    console.log(err.message);\n}","i":[]},{"p":33,"t":"4.     Create a node app to check whether a number is positive; if not throw an\nexception.\nfunction positive(a){\n    if(a<0)\n    {\n           throw new Error(a+ \" IS NOT POSITIVE\");\n    }\n    else\n           {\n           console.log(a+ \"IS POSITIVE\");\n    }\n}\n\ntry{\n    positive(-90);\n}\ncatch(err){\n    console.log(err.message);\n\n}","i":[]}]},{"n":17,"title":"Promises in Node.js","page":34,"pages":[{"p":34,"t":"Promises in Node.js\n  1. Create a promise to check whether a number is greater than any specific number. If\n     it is greater trigger a success; else trigger a failure.\n     var prom= new Promise(function(resolve,reject)\n     {\n            var num1=5;\n            var num2=10;\n\n         if(num1>num2)\n         {\n             resolve (\"success \"+num1+ \" is greater than \" +num2);\n         }\n         else\n         {\n             reject (\"failure! \" +num1+ \" is not greater than \"\n     +num2);\n         }\n     });\n\n     prom.then(function(message){\n         console.log(message);\n     })\n\n     .catch(function(message){\n         console.log(message);\n     })","i":[]},{"p":35,"t":"2.   Create a program to check whether a number is positive or negative.\n     var prom= new Promise(function(resolve,reject)\n     {\n       var num1=-5;\n\n           if(num1>0)\n           {\n              resolve (\"success! \"+num1+ \" is positive\");\n           }\n           else\n           {\n              reject (\"failure! \" +num1+ \" is negative\");\n           }\n     });\n\n     prom.then(function(message){\n        console.log(message);\n     })\n\n     .catch(function(message){\n        console.log(message);\n     })","i":[]},{"p":36,"t":"3.   Create a promise to check whether the internet speed is stable or not.\n     var prom= new Promise(function(resolve,reject)\n     {\n          var curr=70;\n          var int=60\n\n           if(curr>int)\n           {\n               resolve (\"internet speed is stable\");\n           }\n           else\n           {\n               reject (\"internet speed is not stable\");\n           }\n     });\n\n     prom.then(function(message){\n         console.log(message);\n     })\n\n     .catch(function(message){\n         console.log(message);\n     })","i":[]},{"p":37,"t":"4.   Create a promise for an asynchronous task set timeout.\n     var prom= new Promise((resolve,reject)=>\n     {\n        setTimeout(()=>\n          {\n               var result= false;\n               if(result)\n               {\n                   resolve(\"Task completed successfully\");\n               }\n               else\n               {\n                   reject(\"Task not completed\");\n               }\n          }, 2000);\n\n     });\n\n     prom.then((message)=>{\n         console.log(message);\n     })\n\n     .catch((message)=>{\n         console.log(message);\n     })","i":[]},{"p":38,"t":"5.   Create a promise for reading a file.\n     const fs= require(\"fs\");\n     var prom = new Promise((resolve, reject)=>\n     {\n          fs.readFile(\"data/sample.txt\", \"utf8\", (err, data)=>\n          {\n               if (err)\n               {\n                   reject(\"error reading the file\");\n               }\n               else\n               {\n                   resolve(data);\n               }\n\n          })\n     })\n\n     prom.then((content)=>\n     {\n         console.log(content);\n     })\n\n     .catch((error)=>\n     {\n         console.log(error)\n     })","i":[]}]},{"n":18,"title":"Promise Chaining","page":39,"pages":[{"p":39,"t":"Promise Chaining\n  1. Create a node.js program that uses promise chaining. The first promise should\n     display your name. The second promise should return your class. Finally display the\n     returned class on the console using .then() chaining.\n\n     var prom = new Promise(function(resolve)\n     {\n         {\n             resolve(\"Samantha\");\n         }\n     });\n\n     prom.then(function(name)\n     {\n         console.log(\"name: \"+name);\n         return \"TYBCA\";\n     })\n     .then(function(classname)\n     {\n         console.log(\"class:\" +classname);\n     })\n\n     .catch(function(error)\n     {console.log(error)});","i":[]},{"p":40,"t":"2.    Check whether the number is greater than 10 or not if greater then call the second\npromise that should check whether the number is even or odd.\n       var prom = new Promise((resolve,reject) => {\n           var num = 9;\n           if(num > 10) {\n                resolve(num);\n           }\n           else {\n                reject(\" Number is not Greater than 10\");\n           }\n      });\n      prom.then(function(num) {\n           console.log(\"Number is greater than 10: \" + num);\n           return num;\n      })\n      .then(function(num) {\n           if (num%2== 0) {\n                console.log(\"Number is even\");\n           }\n           else {\n                console.log(\"Number is odd\");\n           }\n\n      })\n      .catch((message) => {\n          console.log(message);\n      });","i":[]}]},{"n":19,"title":"Command Line Arguments","page":41,"pages":[{"p":41,"t":"Command Line Arguments\n     1. Display command line arguments.\n\n        console.log(\"arguments:\");\n        for(var i=0; i<process.argv.length; i++)\n        {\n            console.log(process.argv[i]);\n        }\n\n\n\n\n2.      To display only the arguments added by the user from the command line.\n\n        console.log(\"arguments:\");\n\n        var arg = process.argv.slice(2);\n\n        for(var i=0; i<arg.length; i++)\n        {\n            console.log(arg[i]);\n        }","i":[]},{"p":42,"t":"Practice Code:\n       1. Accepting the following numbers from the user in the command line\n       (23,24,25,26,27,70,12,80). Using the slice method to display the sum of the numbers.\nconsole.log(\"values:\");\n\n       var arg = process.argv.slice(2);\n       var sum=0;\n       for(var i=0; i<arg.length; i++)\n       {\n           sum=sum+parseInt(arg[i]);\n           console.log(arg[i]);\n\n       }\n\n       console.log(\"The sum of the array elements are: \" + sum);","i":[]}]},{"n":20,"title":"Readable Streams","page":43,"pages":[{"p":43,"t":"Readable Streams\nconst fs=require(\"fs\");\n\n//create readable stream\n\nconst readStream = fs.createReadStream(\"sample.txt\", {encoding:\n\"utf8\", highWaterMark:1024});\n\n//read the file chunk by chunk (.on for reading)\n\nreadStream.on(\"data\", function(chunk) //the data event is triggered\nhere whenever a chunk of data is available\n\n{\n    console.log(\"recieved chunk:\", chunk);\n});\nreadStream.on(\"end\", function()\n{\n    console.log(\"file reading complete\");\n});\n\nreadStream.on(\"error\", function(err)\n{\n    console.log(err.message);\n});","i":[]}]},{"n":21,"title":"Writable Streams","page":44,"pages":[{"p":44,"t":"Writable Streams\n  1. Write to a file or another document\n     const fs=require(\"fs\");\n     const path=require(\"path\");\n\n     try{\n\n         const filepath= path.join(__dirname, \"data\", \"file1.txt\");\n         const writeStream= fs.createWriteStream(filepath, \"utf8\");\n         writeStream.write(\"thank you for sunshine, thank you for\n     rain, thank you for joy, thank you for pain\");\n         writeStream.write(\"THANK YOU EVERYONE\" , ()=>\n         {\n             console.log(\"data written successfully\");\n         });\n         writeStream.end();\n     }\n\n     catch(err){\n         console.log(err);\n     };","i":[]},{"p":45,"t":"2.   Write to a file called duplicate.txt from a dummy file and ensure it is all uppercase.\n     const fs=require(\"fs\");\n     const path=require(\"path\");\n\n     try{\n         const readfilepath=path.join(__dirname, \"data\", \"dummy.txt\");\n         const writefilepath=path.join(__dirname, \"data\",\n     \"duplicate.txt\");\n\n         const readstream = fs.createReadStream(readfilepath, \"utf8\");\n         const writeStream= fs.createWriteStream(writefilepath,\n     \"utf8\");\n         readstream.on(\"data\", function(chunk) //writes the data to\n     the file\n         {\n             chunk=chunk.toUpperCase();\n             writeStream.write(chunk);\n         });\n\n          readstream.on(\"error\", function(err) //checks error\n          {\n              console.log(err);\n\n          });\n\n          readstream.on(\"end\", function() //clears buffer\n          {\n              writeStream.end();\n              console.log(\"finished reading the file\");\n          });\n\n\n          writeStream.on(\"finish\", function() //finish writing data\n          {\n              console.log(\"data written successfully\");\n          });\n     }\n\n     catch(err)\n     {\n         console.log(err);\n\n     }","i":[]},{"p":46,"t":"","i":[]}]},{"n":22,"title":"Pipe","page":47,"pages":[{"p":47,"t":"Pipe\nconst fs= require(\"fs\");\nconst path=require(\"path\");\n\ntry{\n    const readpath= path.join(__dirname, \"data\", \"dummy.txt\");\n    const writepath= path.join(__dirname, \"data\", \"pipefile.txt\");\n\n    const readstream=fs.createReadStream(readpath, \"utf8\");\n    const writestream= fs.createWriteStream(writepath, \"utf8\");\n\n    readstream.pipe(writestream);\n    readstream.on(\"end\", function() //clears buffer\n    {\n        writestream.end();\n        console.log(\"finished reading the file\");\n    });\n\n\n    writestream.on(\"finish\", function() //finish writing data\n    {\n        console.log(\"data written successfully\");\n    });\n\n}\ncatch(err)\n{\n    console.log(err);\n\n}","i":[]}]},{"n":23,"title":"Standard Streams","page":48,"pages":[{"p":48,"t":"Standard Streams\n 1. Using stdin take input of user name and display output using stdout.\n    process.stdin.setEncoding(\"utf8\");\n    console.log(\"enter your name:\");\n    process.stdin.on(\"data\", (name)=>\n    {\n          process.stdout.write(\"your name is \"+name.trim())\n          process.exit();\n    })\n\n\n\n\n 2. Check if the number entered by user is a number or not\n    process.stdin.setEncoding(\"utf8\");\n    console.log(\"enter a number:\");\n    process.stdin.on(\"data\", (number)=>\n    {\n        if(isNaN(number))\n        {\n               process.stdout.write(number.trim() + \" is not a number\");\n        }\n        else\n        {\n               process.stdout.write(number.trim() + \" is a number\");\n        }process.exit();\n    })","i":[]},{"p":49,"t":"3. To take array values from user, print the array and then the sum\n\n    process.stdin.setEncoding(\"utf8\")\n    console.log(\"enter array values:\");\n    process.stdin.on(\"data\", (input)=>\n    {\n        var arr= input.trim().split(\" \").map(Number)\n        process.stdout.write(\"the array values are: \" + arr)\n        var sum =arr.reduce((total, num)=>total+num,0)\n        process.stdout.write(\"\\n the sum is \" +sum);\n        process.exit();\n    })","i":[]}]},{"n":24,"title":"Routes in Node.js (using Postman app)","page":50,"pages":[{"p":50,"t":"Routes in Node.js (using postman app)\n  1.   Get request to take data\n       const express = require(\"express\");\n       const app= express();\n\n       const port =3000;\n       app.listen(port,()=>\n       {\n           console.log(\"server is running\");\n       });\n\n       app.get('/', (req,res)=>\n       {\n           res.send(\"this is homepage\");\n       });\n\n       app.get('/about_us', (req,res)=>\n       {\n           res.send(\"we are the dreamers who make it happen\");\n       });","i":[]},{"p":51,"t":"2. Get request to accept query parameters\nconst express = require(\"express\");\nconst app= express();\n\nconst port =3000;\napp.listen(port,()=>\n{\n    console.log(\"server is running\");\n});\n\napp.get('/login', (req,res)=>\n{\n    const fname= req.query.firstname;\n    const lname= req.query.lastname;\n    res.send(\"Your full name is: \"+fname + \" \" +lname);\n});","i":[]},{"p":52,"t":"3. Get request to accept a route parameter\nconst express = require(\"express\");\nconst app= express();\n\nconst port =3000;\napp.listen(port,()=>\n{\n    console.log(\"server is running\");\n});\n\napp.get('/data/:email/:phone', (req,res)=>\n{\n    const em=req.params.email;\n    const ph=req.params.phone;\n    res.send(\"Your email is: \"+em + \" and your contact number is \"\n+ph);\n});","i":[]},{"p":53,"t":"4. Get request to access external html pages\nconst express = require(\"express\");\nconst app= express();\n\nconst port =3000;\napp.listen(port,()=>\n{\n    console.log(\"server is running\");\n});\n\nconst path=require(\"path\");\n\napp.get('/dashboard', (req,res)=>\n{\n    res.sendFile(path.join(__dirname, \"view\",\n\"dashboard.html\")); //directly access file\n});\n\nDashboard.html\n<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <title>Dashboard using Express</title>\n    </head>\n    <body>\n        <table>\n            <tr>\n                 <th>Roll No</th>\n                 <th>Name</th>\n            </tr>\n            <tr>\n                 <td>\n                     101\n                 </td>\n                 <td>\n                     Samantha\n                 </td>\n            </tr>\n            <tr>\n                 <td>\n                     102\n                 </td>\n                 <td>\n                     Krishna\n                 </td>","i":[]},{"p":54,"t":"            </tr>\n            <tr>\n                 <td>\n                     103\n                 </td>\n                 <td>\n                     Nash\n                 </td>\n            </tr>\n        </table>\n    </body>\n</html>","i":[]},{"p":55,"t":"5. Using post request to accept a query parameters\nconst express = require(\"express\");\nconst app= express();\n\nconst port =3000;\napp.listen(port,()=>\n{\n    console.log(\"server is running\");\n});\napp.use(express.urlencoded({extended:true}));\n\napp.post('/sign_in',(req, res)=>\n{\n    const uname=req.body.username;\n    const pass= req.body.password;\n    res.send(\"Your user name is: \" +uname + \" password is: \" +pass);\n});","i":[]},{"p":56,"t":"6. Post request to login\n   const express = require(\"express\");\n   const app= express();\n\n  const port =3000;\n  app.listen(port,()=>\n  {\n      console.log(\"server is running\");\n  });\n  app.use(express.urlencoded({extended:true}));\n  app.post('/login',(req, res)=>\n  {\n      const uname=req.body.username;\n      const pass= req.body.password;\n      if(uname==\"admin\"&&pass==\"1234\")\n      {\n          res.send(\"Your user name is: \" +uname + \" password is: \"\n  +pass);\n      }\n      else\n      {\n          res.send(\"Invalid username or password\");\n      }\n  });","i":[]},{"p":57,"t":"Practice Codes:\n6.     1. Post request to add two numbers\n       const express = require(\"express\");\n       const app= express();\n\n     const port =3000;\n     app.listen(port,()=>\n     {\n         console.log(\"server is running\");\n     });\n     app.use(express.urlencoded({extended:true}));\n\n     app.post('/add', (req,res)=>\n     {\n         const num1=Number(req.body.number1);\n         const num2=Number(req.body.number2);\n         const sum=num1+num2;\n         res.send(num1+ \" + \" +num2+ \" = \" +sum)\n     });","i":[]},{"p":58,"t":"     2. Student Registration System. Use GET to display welcome details and retrieve\n     student details. Use POST to submit student details(roll, name, course). Use POST to\n     calculate the students total and average(any 3 subjects)\n     const express = require(\"express\");\n     const app= express();\n\n     const port =3000;\n     app.listen(port,()=>\n     {\n         console.log(\"server is running\");\n     });\n     app.use(express.urlencoded({extended:true}));\n\n     app.get('/welcome',(req, res)=>\n     {\n         res.send(\"Hi everyone\");\n     });\n\n     app.get('/retrive', (req,res)=>\n     {\n         const roll=req.query.rollnumber;\n         const na= req.query.name;\n         const add= req.query.address\n         res.send(\"Roll Number: \" +roll+ \"\\n Name: \" +na+ \"\\n Address:\n\" +add);\n     });\n\n     app.post('/login',(req, res)=>\n     {\n         const roll=req.body.rollnumber;\n         const name= req.body.name;\n         const cour= req.body.course;\n\n         res.send(\"Roll Number: \" +roll+ \"\\n Name: \" +name+ \"\\n\nCourse: \" +cour);\n\n     });\n\n     app.post('/marks',(req, res)=>\n     {\n         const sub1=Number(req.body.subject1);\n         const sub2=Number(req.body.subject2);\n         const sub3=Number(req.body.subject3);\n         var sum= sub1+sub2+sub3;\n         var avg= sum/3;","i":[]},{"p":59,"t":"         res.send(\"MARKS: \\n\" +\"Subject 1: \" +sub1 +\"\\n Subject 2: \"\n+sub2+\"\\n Subject 3: \" +sub3 + \"\\n TOTAL: \"+ sum +\"\\n AVERAGE: \"+\navg);\n\n     });","i":[]},{"p":60,"t":"","i":[]}]},{"n":25,"title":"Gateway","page":61,"pages":[{"p":61,"t":"Gateway\nconst express=require(\"express\");\nconst{createProxyMiddleware}=require('http-proxy-middleware');\n//allows us to forward request from 1 server to another server\n\nconst app=express();\n\napp.use('/', createProxyMiddleware({\n    target:'http://localhost:3000',\n    changeOrigin:true\n}));\n\napp.listen(5000, ()=>\n{\n    console.log(\"gateway server is running\")\n});","i":[]}]},{"n":26,"title":"Cron","page":62,"pages":[{"p":62,"t":"Cron\n  1. Run a task every minute.\n     const cron= require('node-cron');\n     cron.schedule('* * * * *' ,()=>\n     {\n          console.log(\"task is running every 1 minute\");\n     });\n\n\n\n\n  2. Display the message “cron task executed successfully” exactly at 9:30 am today\n      const cron=require('node-cron');\n      cron.schedule('25 9 13 8 ', ()=> //*/2 implies after 2 minutes\n      {\n           console.log(\"cron task completed successfully\");\n           job.stop(); //stops execution after single completion\n      });\n\n\n\n\n  3. Display a message after 30 seconds on every thursday of august\n      const cron=require('node-cron');\n      cron.schedule(\"*/30 45-59 9 * 8 4\", ()=>\n      {\n           console.log(\"task running after 30 seconds on thursdays of\n      August\");\n\n       });\n\n\n\n\n  4. Write a code to display a message every minute from 51-59th minute of the hour.\n      const cron= require('node-cron');\n      cron.schedule('51-59/1 * * * *', ()=>\n      {\n              console.log(\"its thursday\");\n      });","i":[]}]},{"n":27,"title":"Webpack: Bundling and Configuration","page":63,"pages":[{"p":63,"t":"Webpack-bundling and configuration\n  1. Install webpack\n\n\n\n\n  message.js\n  const message = \"hello everyone\";\n  module.exports=message;\n  index.js\n  const message= require('./message')\n  console.log(message);\n  Creates main.js in dist folder //bundled index and message\n  (()=>{var o={756(o){o.exports=\"hello everyone\"}};const\n  e={},r=function r(t){const n=e[t];if(void 0!==n)return\n  n.exports;const s=e[t]={exports:{}};return\n  o[t](s,s.exports,r),s.exports}(756);console.log(r)})();","i":[]},{"p":64,"t":"2.   Create a config file\n     index.js\n     const express=require('express');\n     const app=express();\n     app.get('/', (req,res)=>\n     {\n          res.send(\"Hello from webpack application\");\n     });\n\n     app.listen(3000,()=>\n     {\n         console.log(\"server is running\");\n     })\n\n     webpack.config.js\n     const path=require('path');\n     module.exports={\n         target: 'node', //in which language\n         entry: './index.js', //which file\n         output:{\n             filename: 'project_bundle.js', //name of file\n             path:path.resolve(__dirname, 'dist') //where file will be\n     stored\n\n          },\n          mode: 'development'\n\n     };","i":[]},{"p":65,"t":"3.     Bundle multiple files using webpacks (index.js , math.js, message.js) and display\noutput.\n       index.js\n       const cal=require('./math');\n       console.log(\"addition:\" +cal.add(10,20));\n       console.log(\"subtraction:\" +cal.sub(30,20));\n       console.log(\"multiplication:\" +cal.multi(30,20));\n       const g=require('./message');\n       console.log(g.greet(\"samantha\"));\n       math.js\n       function add(a,b)\n       {return a+b;}\n       function sub(a,b)\n       {return a-b;}\n       function multi(a,b)\n       {return a*b;}\n       module.exports={add,sub,multi};\n       message.js\n       function greet(name)\n       {\n           console.log(\"good day \" +name);\n       }\n\n       module.exports={greet};","i":[]}]},{"n":28,"title":"Sequelize","page":66,"pages":[{"p":66,"t":"Sequelize\n  1. Create a database using PHPmyAdmin. Install sequelize and create model. Test and\n     sync the model.\n\n\n\n     Creating connection\n     const {Sequelize}= require(\"sequelize\")\n     const sequelize = new Sequelize(\n         'college_db',\n         'root',\n         'student',\n         {\n             host:'localhost',\n             dialect: 'mysql'\n         }\n     );\n\n     module.exports=sequelize;\n\n     Testing connection\n     const sequelize=require('./db');\n     async function testConnection() {\n         try{\n             await sequelize.authenticate\n         }\n         catch(error)\n         {\n             console.log(\"unable to connect to db\")\n         }\n         finally{\n             await sequelize.close();\n         }\n\n     }\n\n     testConnection();\n\n     Creating Student Module layout\n     const {DataTypes}=require('sequelize');\n     //import the sequelize connection\n     const sequelize=require('../db');\n\n     //create student module","i":[]},{"p":67,"t":"const Student= sequelize.define('Student',{\n    name:{\n        type:DataTypes.STRING,\n        allowNull: false,\n    },\n    age:{\n        type:DataTypes.INTEGER,\n        allowNull:false,\n    },\n    course:{\n        type:DataTypes.STRING,\n        allowNull:false,\n    }\n});\n\nCreating the link to create table\nconst sequelize=require('./db');\nconst student=require('./model/student');\nasync function syncdb() {\n    try{\n        await sequelize.sync();\n        console.log(\"student table created\");\n    }\n    catch(error)\n    {\n        console.log(\"error creating table\"+error);\n    }\n    finally\n    {\n        await sequelize.close();\n    }\n}\n\nsyncdb();","i":[]},{"p":68,"t":"CREATE A TEACHER TABLE\nconst {DataTypes}=require('sequelize');\n//import the sequelize connection\nconst sequelize=require('../db');\n\n//create teacher module\nconst Teacher= sequelize.define('Teacher',{\n    id:{\n        type:DataTypes.INTEGER,\n        autoIncrement: true,\n        primaryKey: true,\n\n      },\n      name:{\n          type:DataTypes.STRING,\n          allowNull: false,\n      },\n      address:{\n          type:DataTypes.STRING,\n          allowNull:false,\n      },\n      phoneno:{\n          type:DataTypes.BIGINT,\n          allowNull:false,\n      }\n});","i":[]},{"p":69,"t":"2.   Insert values into table\n     const db = require('./db');\n     const Std=require('./model/student');\n\n     async function insertStudent()\n     {\n        try{\n            await db.authenticate()\n                const newstudent = await Std.create({\n                    name: \"Samantha\",\n                    age: 20,\n                    course:\"BCA\",\n\n                 });\n                 console.log(\"data inserted successfully\");\n                 console.log(newstudent.toJSON());\n          }\n          catch(error)\n          {\n              console.log(error);\n          }\n          finally\n          {\n              await db.close();\n          }\n     };\n\n     insertStudent();","i":[]},{"p":70,"t":"Relationships using Seqeuelize\n\n   1. One-To-One Relationship\nconst Employee=require('./models/employee');\nconst EmployeeProfile=require('./models/employeeProfile');\n\nEmployee.hasOne(EmployeeProfile);\nEmployeeProfile.belongsTo(Employee);\n\nmodule.exports={\n    Employee,\n    EmployeeProfile\n};","i":[]},{"p":71,"t":"","i":[]},{"p":72,"t":"2.   One to Many\n\nconst Employee=require('./models/employee');\nconst Department=require('./models/department');\n\n//one to many\nDepartment.hasMany(Employee);\nEmployee.belongsTo(Department);\n\nmodule.exports={\n    Employee,\n    Department\n};","i":[]},{"p":73,"t":"3.   Many to Many\n\nconst Employee=require('./models/employee');\nconst Project=require('./models/project');\n\n\n//many to many\nEmployee.belongsToMany(Project,{\n    through:'EmployeeProject'\n});\nProject.belongsToMany(Employee,{\n    through:'EmployeeProject' //junction table\n});\n\nmodule.exports={\n    Employee,\n    Project\n};","i":[]}]},{"n":29,"title":"Migration","page":74,"pages":[{"p":74,"t":"Migration\nHistory of what has to be communicated\nSequelize creates migration file containing instructions and executes\non mysql\nModel represents a table,\nMigration is a file.\n2 important parts - Up and Down\n   1. Perform a migration\nNpm init -y\nNpm install sequelize mysql2\nnpm install --save-dev sequelize-cli\nNpx sequelize-cli init\nnpx sequelize-cli migration:generate --name create_students\n\n'use strict';\n\n/** @type {import('sequelize-cli').Migration} */\nmodule.exports = {\n  async up (queryInterface, Sequelize) { //tell sequelize what should\nhappen when this migration is executed\n    await queryInterface.createTable('Students', {\n      id:{\n        type:Sequelize.INTEGER,\n        primaryKey:true,\n        autoIncrement:true,\n        allowNull:false\n      },\n      name:{\n        type: Sequelize.STRING,\n        allowNull:false\n      },\n      age:{\n        type:Sequelize.INTEGER,\n        allowNull:false,\n      },\n      createdAt:{\n        type:Sequelize.DATE,\n        allowNull:false,\n      },\n      updatedAt:{\n        type:Sequelize.DATE,\n        allowNull:false,\n      }\n    });","i":[]},{"p":75,"t":"    },\n\n  async down (queryInterface, Sequelize) { //used to undo changes\n  await queryInterface.dropTable('Students');\n  }\n};\n\n{\n    \"development\": {\n      \"username\": \"root\",\n      \"password\": \"student\",\n      \"database\": \"student_db\",\n      \"host\": \"127.0.0.1\",\n      \"dialect\": \"mysql\"\n    },\n    \"test\": {\n      \"username\": \"root\",\n      \"password\": \"student\",\n      \"database\": \"student_db\",\n      \"host\": \"127.0.0.1\",\n      \"dialect\": \"mysql\"\n    },\n    \"production\": {\n      \"username\": \"root\",\n      \"password\": \"student\",\n      \"database\": \"student_db\",\n      \"host\": \"127.0.0.1\",\n      \"dialect\": \"mysql\"\n    }\n}","i":[]},{"p":76,"t":"npx sequelize-cli db:migrate:undo (to drop table)","i":[]}]},{"n":30,"title":"Model Querying","page":77,"pages":[{"p":77,"t":"Model Querying\nnpx sequelize-cli model:generate --name employee --attributes\nname:string,gender:string,contact:string //creates the model file\n\n\n\n   1. Insert data into table using postman\nemployee.js\n'use strict';\nconst {\n  Model\n} = require('sequelize');\nmodule.exports = (sequelize, DataTypes) => {\n  class employee extends Model {\n     /**\n      * Helper method for defining associations.\n      * This method is not a part of Sequelize lifecycle.\n      * The `models/index` file will call this method automatically.\n      */\n     static associate(models) {\n       // define association here\n     }\n  }\n  employee.init({\n     name: DataTypes.STRING,\n     gender: DataTypes.STRING,\n     contact: DataTypes.STRING\n  }, {\n     sequelize,\n     modelName: 'employee',\n  });\n  return employee;\n};\n\nindex.js\n'use strict';\n\nconst fs = require('fs');\nconst path = require('path');\nconst Sequelize = require('sequelize');\nconst process = require('process');\nconst basename = path.basename(__filename);\nconst env = process.env.NODE_ENV || 'development';\nconst config = require(__dirname + '/../config/config.json')[env];","i":[]},{"p":78,"t":"const db = {};\n\nlet sequelize;\nif (config.use_env_variable) {\n  sequelize = new Sequelize(process.env[config.use_env_variable],\nconfig);\n} else {\n  sequelize = new Sequelize(config.database, config.username,\nconfig.password, config);\n}\n\nfs\n  .readdirSync(__dirname)\n  .filter(file => {\n    return (\n      file.indexOf('.') !== 0 &&\n      file !== basename &&\n      file.slice(-3) === '.js' &&\n      file.indexOf('.test.js') === -1\n    );\n  })\n  .forEach(file => {\n    const model = require(path.join(__dirname, file))(sequelize,\nSequelize.DataTypes);\n    db[model.name] = model;\n  });\n\nObject.keys(db).forEach(modelName => {\n  if (db[modelName].associate) {\n    db[modelName].associate(db);\n  }\n});\n\ndb.sequelize = sequelize;\ndb.Sequelize = Sequelize;\n\nmodule.exports = db;","i":[]},{"p":79,"t":"index.js (user defined)\nconst express= require(\"express\");\nconst app= express();\nconst port=3000;\nconst db=require('./models');\nconst emp=db.employee;\napp.use(express.json());\n\ndb.sequelize.sync()\n.then(()=>{\nconsole.log(\"database table created\");\n})\n\n.catch((err)=>\n{\n    console.log(err);\n});\n\n//insert employee\n\napp.post('/insert_employee', async(req,res)=>\n{\n    try{\n        console.log(req.body);\n        const inem=await emp.create(req.body);\n        res.status(201).json(inem);\n\n      }\n      catch(err){\n          res.status(500).json({messsage:\"something went wrong\" +err})\n      }\n});\n\napp.listen(port,()=>\n{\n    console.log(\"server is running on port\" +port)\n});\n\nMigration file\n'use strict';\n/** @type {import('sequelize-cli').Migration} */\nmodule.exports = {\n  async up(queryInterface, Sequelize) {\n    await queryInterface.createTable('employees', {\n      id: {","i":[]},{"p":80,"t":"        allowNull: false,\n        autoIncrement: true,\n        primaryKey: true,\n        type: Sequelize.INTEGER\n      },\n      name: {\n        type: Sequelize.STRING\n      },\n      gender: {\n        type: Sequelize.STRING\n      },\n      contact: {\n        type: Sequelize.STRING\n      },\n      createdAt: {\n        allowNull: false,\n        type: Sequelize.DATE\n      },\n      updatedAt: {\n        allowNull: false,\n        type: Sequelize.DATE\n      }\n    });\n  },\n  async down(queryInterface, Sequelize) {\n    await queryInterface.dropTable('employees');\n  }\n};","i":[]},{"p":81,"t":"","i":[]},{"p":82,"t":"2.    Use postman and find employee using id\n*edited user defined index.js\napp.get('/find_employee/:id', async(req,res)=>\n{\n    try{\n         const employee=await emp.findByPk(req.params.id);\n         if(!employee)\n         {\n              return res.status(404).send(\"employee not found\");\n         }\n         res.json(employee);\n    }\n    catch(err)\n    {\n         res.status(500).send(err.message);\n    }\n})","i":[]},{"p":83,"t":"3.   Finding all employee\napp.get('/findall_employee', async(req,res)=>\n{\n    try{\n        const employees= await emp.findAll();\n        res.status(200).json(employees);}\n        catch(err)\n        {\n             console.log(err);\n             res.status(500).json({\n                   message: \"error fetching details\",\n                   error: err.message\n             });\n        }\n});","i":[]},{"p":84,"t":"  4. Finding employees using findOne\napp.get('/find_contact', async(req,res)=>\n{\n    try{\n         const cont=req.query.contact;\n         const employee= await emp.findOne({\n              where:{\n                  contact:cont\n              }\n         });\n    if(!employee)\n    {\n         return res.status(404).json({\n              message:\"employee not found\"\n         });\n    }\n    res.status(200).json(employee);\n    }\n    catch(err){\n         res.status(500).json({\n              message: \"error\"\n         });\n\n      }\n});","i":[]},{"p":85,"t":"  5. Update\napp.put('/updatedata', async(req,res)=>\n{\n    try{\n        const sid= req.query.id;\n        const[result]=await emp.update(req.body,{\n            wherre:{id:sid}\n        });\n        if(result>0)\n        {\n            res.status(201).json({message: \"rows updated\"});\n        }\n        else\n        {\n            res.status(201).json({message: \"no rows updated\"})\n        }\n    }\n    catch(err)\n    {\n        res.status(500).send(err.message);\n    }\n});","i":[]},{"p":86,"t":"  6. Delete (Destroy)\napp.delete('/deleterow/:id', async(req,res)=>\n{\n    try{\n         const sid= req.params.id;\n         const del= await emp.destroy({\n              where:{\n                   id:sid\n              }\n         });\n         if(del>0){\n              res.status(201).json({\n                   message: \"rows deleted successfully\"\n         });}\n         else\n         res.status(201).json({message: \"no rows were deleted\"});\n         }\n         catch(err){\n              res.status(500).json({\n                   message: \"something went wrong\"+err\n              })\n         }\n});","i":[]}]},{"n":31,"title":"Validations and Constraints","page":87,"pages":[{"p":87,"t":"Validations and Constraints\nconst {DataTypes} = require(\"sequelize\");\nconst db= require(\"../db\");\nconst user= db.define(\"user\", {\n    id:{\n        type: DataTypes.INTEGER,\n        primaryKey: true,\n        allowNull: false,\n        autoIncrement: true\n    },\n\n    name:{\n        type: DataTypes.STRING, //constraints\n        allowNull: false,\n        validate: {\n            max:50 //validation\n        }\n\n    },\n\n    email:{\n        type: DataTypes.STRING,\n        allowNull: false,\n        unique: true,\n        validate: {\n            max: 150,\n            notEmpty: true,\n            isEmail: true\n        }\n    },\n\n    DOB:{\n        type:DataTypes.DATE,\n        allowNull: false,\n        validate: {\n            isDate: true,\n            isBefore: \"2006-12-31\",\n            isAfter: \"1995-12-01\"\n        }\n    },\n\n    gender: {\n        type: DataTypes.STRING,\n        allowNull: false,","i":[]},{"p":88,"t":"         validate:{\n             isIn:[[\"Male\", \"Female\", \"Transgender\"]],\n         }\n    },\n\n    password: {\n        type: DataTypes.STRING,\n        validate: {\n            notEmpty: true,\n            len:[8,12]\n        }\n    }\n}\n\napp.js\nconst express = require(\"express\");\nconst app=express();\nconst user= require(\"./model/user\");\napp.use(express.json());\napp.post(\"/users\", async(req,res)=>\n{\n    try{\n        const newuser= await user.create;\n        res.status(201).json(newuser);\n    }\n    catch(err){\n        res.status(500).json({\n            message: \"something went wrong\"+err\n        });\n    }\n});\n\napp.listen(3000, ()=>\n{\n    console.log(\"server is running\")\n})","i":[]},{"p":89,"t":"","i":[]}]},{"n":32,"title":"Raw Queries","page":90,"pages":[{"p":90,"t":"Raw Queries\n   1. Insert\nconst express=require('express');\nconst app=express();\nconst port=3000;\nconst sequelize= require(\"./db\");\napp.use(express.json());\n\n//insert\n\napp.post('/insert', async(req,res)=>\n{\n    try{\n        const nam = req.body.name;\n        const gen = req.body.gender;\n        const cont = req.body.contact;\n        const now = new Date();\n        const result = await sequelize.query(\n            `INSERT INTO employees (name, gender, contact, createdAt,\nupdatedAt)\n            VALUES(?,?,?,?,?)`,\n            {replacements:[nam,gen,cont,now,now],\n            type:sequelize.QueryTypes.INSERT}\n        );\n        const count =result[1];\n        if(count>0)\n        {\n            res.status(201).json({\n                mesasge: \"Rows inserted\"\n            });\n        }\n        else{\n            res.status(400).json({\n                message:\"rows not inserted\"\n            });\n        }\n    }\n    catch(err)\n    {\n        res.status(500).json({\n            message:\"something went wrong\"+err\n        });\n    }\n});","i":[]},{"p":91,"t":"app.listen(port,()=>\n{\n    console.log(\"server is running\")\n});","i":[]},{"p":92,"t":"2.   Select by Id\n\napp.get('/selectbyid', async(req,res)=>\n{\n    try{\n        const sid=req.query.id;\n        const result=await sequelize.query(\n            `SELECT * FROM employees WHERE id=?`,\n            {\n                replacements:[sid],\n                type:sequelize.QueryTypes.SELECT\n            }\n        );\n        res.status(200).json(result);\n    }\n    catch(err)\n    {\n        res.status(500).json({\n            message:\"something went wrong\"+err\n        });\n    }\n});","i":[]},{"p":93,"t":"3.    Update\napp.put('/update', async(req,res)=>\n{\n    try{\n        const sid=req.query.id;\n        const contact= req.body.contact;\n        const now = new Date();\n        const result= await sequelize.query(\n             `UPDATE employees SET contact=?, updatedAt=? WHERE id=?`,\n             {\n                 replacements:[contact, now, sid],\n                 type:sequelize.QueryTypes.UPDATE\n             }\n        );\n        const rows=result[1];\n        if(rows>0){\n             res.status(200).json({\n                 message: \"row updated\"\n             });\n        }\n        else{\n             res.status(400).json({\n                 message:\"row updation failed\"\n             });\n        }\n    }\n    catch(err)\n    {\n        res.status(500).json({\n             message: \"something went wrong\"+err\n        });\n    }\n})","i":[]},{"p":94,"t":"","i":[]},{"p":95,"t":"4.    Delete\napp.delete('/delete', async(req,res)=>\n{\n    try{\n         const sid=req.query.id;\n         const result=await sequelize.query(\n             `DELETE FROM employees WHERE id=?`,\n             {\n                 replacements:[sid],\n                 type:sequelize.QueryTypes.DELETE\n             }\n         );\n         res.status(200).json({\n             message: \"row deleted\"\n         });\n    }\n    catch(err)\n    {\n         res.status(500).json({\n             message:\"something went wrong\"+err\n         });\n    }\n});","i":[]}]},{"n":33,"title":"Frontend Framework: Install and Create React App","page":96,"pages":[{"p":96,"t":"Frontend Framework- install and create react app\nMicrosoft Windows [Version 10.0.26100.3476]\n(c) Microsoft Corporation. All rights reserved.\n\nD:\\react_js>npm create vite@latest first-app -- --template react\n\n> npx\n> create-vite first-app --template react\n\n│\n◇ Which linter to use?\n│ ESLint\n│\n◇ Install with npm and start now?\n│ Yes\n│\n◇ Scaffolding project in D:\\react_js\\first-app...\n│\n◇ Installing dependencies with npm...\n\nadded 143 packages, and audited 144 packages in 48s\n\n31 packages are looking for funding\n  run `npm fund` for details\n\nfound 0 vulnerabilities\n│\n◇ Starting dev server...\n\n> first-app@0.0.0 dev\n> vite\n\n VITE v8.3.0   ready in 1276 ms\n\n ➜   Local:    http://localhost:5173/\n ➜   Network: use --host to expose\n ➜   press h + enter to show help","i":[]},{"p":97,"t":"App.jsx\nimport { useState } from 'react'\nimport heroImg from './assets/hero.png'\nimport reactLogo from './assets/react.svg'\nimport viteLogo from './assets/vite.svg'\nimport './App.css'\nimport IdCard from './idCard'\nfunction App() { //component name always captial\n  return ( <>\n  <h1>This is my first REACT app</h1>\n  </>\n)\n\n}\n\nexport default App","i":[]}]},{"n":34,"title":"Props and Hooks","page":98,"pages":[{"p":98,"t":"Props and Hooks\n 1.   Props\n      function IdCard(props){\n          return (\n              <>\n              <h3>your name: {props.name}</h3>\n              <h4>your rollno: {props.rollno}</h4></>\n          );\n      }\n      export default IdCard\n\n      //parent component\n      import { useState } from 'react'\n      import heroImg from './assets/hero.png'\n      import reactLogo from './assets/react.svg'\n      import viteLogo from './assets/vite.svg'\n      import './App.css'\n      import IdCard from './idCard'\n      function App() {\n        return ( <>\n        <h1>This is my first REACT app</h1>\n        <p>Student details</p>\n        <IdCard name=\"SAM\" rollno= \"37\"/>\n        </>\n      )\n\n      }\n      export default App","i":[]},{"p":99,"t":"2. Use State Hook\n   Counter.jsx\n   import { useState } from \"react\";\n\n  function Counter(){\n      const [count, setCount]= useState(0)\n      return(\n          <>\n          <h2>Current Count: {count}</h2>\n          <button onClick={()=>setCount(count+1)}>Increase\n  Count</button>\n          <button onClick={()=>setCount(count-1)}>Decrease\n  Count</button></>\n      )\n  }\n  export default Counter;\n\n  App.jsx\n  import { useState } from 'react'\n  import heroImg from './assets/hero.png'\n  import reactLogo from './assets/react.svg'\n  import viteLogo from './assets/vite.svg'\n  import './App.css'\n  import IdCard from './idCard'\n  import Counter from './counter.jsx'\n  function App() {\n    return ( <>\n    <h1>This is my first REACT app</h1>\n    <p>Student details</p>\n    <IdCard name=\"SAM\" rollno= \"37\"/>\n    <Counter></Counter>\n    </>}\n  }\n  export default App","i":[]},{"p":100,"t":"3. Use State and Props\n   import { useState } from \"react\";\n   function Greeting(props){\n        const [mood, setMood]=useState(\"HAPPY\");\n        return(\n             <>\n             <h2>Hello!! {props.name}</h2>\n             <p>{props.name} is feeling {mood} </p>\n             <button onClick={()=>setMood(\"EXCITED\")}> EXCITED\n   </button>\n             <button onClick={()=>setMood(\"SLEEPY\")}> SLEEPY </button>\n             </>\n        )\n   }\n\n  export default Greeting;\n\n  import { useState } from 'react'\n  import heroImg from './assets/hero.png'\n  import reactLogo from './assets/react.svg'\n  import viteLogo from './assets/vite.svg'\n  import './App.css'\n  import IdCard from './idCard'\n  import Counter from './counter.jsx'\n  import Greeting from './greetings.jsx'\n\n  function App() {\n    return ( <>\n    <h1>This is my first REACT app</h1>\n    <p>Student details</p>\n    <IdCard name=\"SAM\" rollno= \"37\"/>\n    <Counter></Counter>\n    <Greeting name=\"Jake\"/>\n    </>\n  )\n\n  }\n\n  export default App","i":[]},{"p":101,"t":"","i":[]},{"p":102,"t":"4. Use Reducer\n   import { useReducer } from \"react\";\n\n  function UseReducer()\n  {\n      const initialstate={\n          username:\"\",\n          pasword:\"\",\n          message:\"\"\n      };\n\n      function reducer(state, action){\n          switch(action.type){\n          case \"setusername\" :\n          return{...state, username:action.value}\n\n          case \"setpassword\" :\n          return{...state, password:action.value}\n\n          case \"login\" :\n              if(state.username===\"Lavina\" && state.password ===\n  \"6767\"){\n                  return{\n                       ...state, message: \"login successful\"\n                  };\n              }\n              else{\n                  return{\n                       ...state, message: \"invalid credentials\"\n                  }\n              }\n              default:\n                  return state;\n          };\n      }\n\n          const[loginvalue, dispatch]=useReducer(\n              reducer, initialstate\n          );\n\n          return(\n              <>\n              <label>Username: </label>\n              <input type=\"text\" value={loginvalue.username}\n  onChange={(e)=>","i":[]},{"p":103,"t":"                dispatch({\n                    type: \"setusername\",\n                    value:e.target.value\n                })}/>\n            <label>Password: </label>\n            <input type=\"text\" value={loginvalue.password}\nonChange={(e)=>\n                dispatch({\n                    type: \"setpassword\",\n                    value:e.target.value\n                })}/>\n            <button\nonClick={()=>dispatch({type:\"login\"})}>Login</button>\n            <h3>{loginvalue.message}</h3>\n            </>\n        );\n\n}\n\nexport default UseReducer;\n\napp.jsx\nimport { useState } from 'react'\nimport heroImg from './assets/hero.png'\nimport reactLogo from './assets/react.svg'\nimport viteLogo from './assets/vite.svg'\nimport './App.css'\nimport UseState from './useState.jsx'\nimport UseReducer from './useReducer.jsx'\nfunction App() {\n  return(\n  <>\n  <h2>1. Use State</h2>\n  <UseState/>\n\n    <h2>2. Use Reducer</h2>\n    <UseReducer/>\n\n    </>\n    )\n}\n\nexport default App","i":[]},{"p":104,"t":"","i":[]},{"p":105,"t":"5. Use Context\n\n   import { createContext, useContext } from \"react\";\n\n   const UserContext= createContext();   //pass or share data between\n   components\n\n   function Greet(){\n       const user=useContext(UserContext);\n       return(\n           <h3>\n               welcome {user.name}-{user.role}\n           </h3>\n       )\n   }\n\n   function UseContext(){\n       const userData={name: \"Soniya\", role:\"Student\"};\n       return(<>\n       <h2>Context provider</h2>\n       <UserContext.Provider\n   value={userData}><Greet/></UserContext.Provider></>)\n   }\n\n   export default UseContext;\n\n   App.jsx\n   import { useState } from 'react'\n   import heroImg from './assets/hero.png'\n   import reactLogo from './assets/react.svg'\n   import viteLogo from './assets/vite.svg'\n   import './App.css'\n   import UseState from './useState.jsx'\n   import UseReducer from './useReducer.jsx'\n   import UseContext from './useContext.jsx'\n\n   function App() {\n     return(\n     <>\n     <h2>1. Use State</h2>\n     <UseState/>\n\n     <h2>2. Use Reducer</h2>\n     <UseReducer/>","i":[]},{"p":106,"t":"    <h2>3. Use Context</h2>\n    <UseContext/>\n    </>\n    )\n}\n\nexport default App","i":[]},{"p":107,"t":"6. Use Ref\n\n   import {useRef, useState} from \"react\";\n\n   function UseRef(){\n       const[seconds,setseconds]=useState(0); //store no. of seconds\n       const timer= useRef(null); // store timer ID\n\n       function startTimer(){\n           if(timer.current===null)\n           {\n               timer.current=setInterval(()=>\n               {\n                   setseconds((prev)=>prev+1);\n               }, 1000);\n           }\n       }\n\n       function stopTimer(){\n           clearInterval(timer.current);\n           timer.current=null;\n           setseconds(0); //resets it back to 0\n       }\n\n       return(\n           <>\n           <h3>Timer: {seconds}</h3>\n           <button onClick={startTimer}>Start</button>\n           <button onClick={stopTimer}>Stop</button>\n           </>\n       )\n\n   }\n\n   export default UseRef;\n\n\n\n\n   app.jsx","i":[]},{"p":108,"t":"import { useState } from 'react'\nimport heroImg from './assets/hero.png'\nimport reactLogo from './assets/react.svg'\nimport viteLogo from './assets/vite.svg'\nimport './App.css'\nimport UseState from './useState.jsx'\nimport UseReducer from './useReducer.jsx'\nimport UseContext from './useContext.jsx'\nimport UseRef from './useRef.jsx'\n\nfunction App() {\n  return(\n  <>\n  <h2>1. Use State</h2>\n  <UseState/>\n\n    <h2>2. Use Reducer</h2>\n    <UseReducer/>\n\n    <h2>3. Use Context</h2>\n    <UseContext/>\n\n    <h2>4. Use Ref</h2>\n    <UseRef/>\n    </>\n\n)\n}\n\nexport default App","i":[]},{"p":109,"t":"7. Use Memo\n\n  import { useState, useMemo } from \"react\";\n  function UseMemo(){\n      const[cartItems]= useState([\n          {name:\"laptop\", price:60000},\n          {name: \"iems\", price:2499},\n          {name: \"television\", price:50000}\n      ]);\n      const[discount, setDiscount]= useState(0);\n      const totalPrice=useMemo(()=>\n      {\n          let total=0;\n          for(let i=0; i<cartItems.length; i++)\n          {\n              total=total+cartItems[i].price\n          }\n          return total-discount;\n      },[cartItems,discount]);\n\n          return(\n              <>\n              <h3>List of Items</h3>\n              <ul>\n                   {cartItems.map((item,index)=>(\n                   <li key={index}>{item.name}-{item.price}</li>))}\n                   </ul>\n                   <h2>Total price: {totalPrice}</h2>\n                   <button\n  onClick={()=>setDiscount(200)}>Discount</button>\n              </>\n          )\n      };\n\n  export default UseMemo;","i":[]},{"p":110,"t":"App.jsx\nimport { useState } from 'react'\nimport heroImg from './assets/hero.png'\nimport reactLogo from './assets/react.svg'\nimport viteLogo from './assets/vite.svg'\nimport './App.css'\nimport UseState from './useState.jsx'\nimport UseReducer from './useReducer.jsx'\nimport UseContext from './useContext.jsx'\nimport UseRef from './useRef.jsx'\nimport UseMemo from './useMemo.jsx'\nfunction App() {\n  return(\n  <>\n  <h2>1. Use State</h2>\n  <UseState/>\n\n    <h2>2. Use Reducer</h2>\n    <UseReducer/>\n\n    <h2>3. Use Context</h2>\n    <UseContext/>\n\n    <h2>4. Use Ref</h2>\n    <UseRef/>\n\n    <h2>5. Use Memo</h2>\n    <UseMemo/>\n    </>\n\n)\n}\n\nexport default App","i":[]},{"p":111,"t":"8. Use Callback\n   import { useState, useCallback } from \"react\";\n\n  function UseCallback(){\n      const[count,setCount]=useState(0);\n      const[name, setName]= useState(\"\");\n\n      const increment=useCallback(()=>{\n          setCount((prev)=>prev+1)\n      }, []); //[] is an empty dependency called a dependency array\n\n      return(\n          <>\n          <h3>Count: {count}</h3>\n          <button onClick={increment}>Increment</button>\n          <input type=\"text\" value={name}\n          onChange={(e)=>setName(e.target.value)} placeholder=\"type\n  yo name\"/>\n          <h3>hello, {name}</h3>\n          </>\n\n      )\n\n  }\n\n  export default UseCallback;\n\n  App.jsx\n  import { useState } from 'react'\n  import heroImg from './assets/hero.png'\n  import reactLogo from './assets/react.svg'\n  import viteLogo from './assets/vite.svg'\n  import './App.css'\n  import UseState from './useState.jsx'\n  import UseReducer from './useReducer.jsx'\n  import UseContext from './useContext.jsx'\n  import UseRef from './useRef.jsx'\n  import UseMemo from './useMemo.jsx'\n  import UseCallback from './useCallback.jsx'\n  function App() {\n    return(\n    <>\n    <h2>1. Use State</h2>\n    <UseState/>\n    <h2>2. Use Reducer</h2>","i":[]},{"p":112,"t":"    <UseReducer/>\n    <h2>3. Use Context</h2>\n    <UseContext/>\n    <h2>4. Use Ref</h2>\n    <UseRef/>\n    <h2>5. Use Memo</h2>\n    <UseMemo/>\n    <h2>6. Use Callback</h2>\n    <UseCallback/>\n    </>\n)\n}\n\nexport default App","i":[]}]},{"n":35,"title":"Routing in React using React Router","page":113,"pages":[{"p":113,"t":"Routing in React using React Router.\n        -   Create the separate routes then call them in the app.jsx\n            Home\n            function Home(){\n                return(\n                    <>\n                    <h1>Home Page</h1>\n\n                    <p>hello world! <br/> Welcome to our website! we\n            are boring</p>\n\n                    </>\n                )\n            }\n\n            export default Home;\n\n            about\n            function Aboutus() {\n              return (\n                <>\n                  <h1>Aboutus Page</h1>\n\n                  <p>\n                    hello world! <br />\n                    We are a non-profit organization that aims to help\n            the world. <br />\n                  </p>\n                </>\n              );\n            }\n\n            export default Aboutus;","i":[]},{"p":114,"t":"contact\nfunction Contact(){\n    return(\n        <>\n        <h1>Contact Page</h1>\n\n        <p>hello world! <br/> You can contact us on:\n        <br/>Mobile: +91 7298356467 <br/> Email:\nworldorg@gmail.com</p>\n\n        </>\n    )\n}\n\nexport default Contact;\n\nregister\nfunction Register(){\n    return(\n         <>\n         <h1>Job Registration Page</h1>\n\n        <p>hello world! <br/>\n        <label>Name: </label>\n        <input type=\"text\"/><br/>\n\n        <label>Email: </label>\n        <input type=\"text\"/><br/>\n\n        <label>Mobile: </label>\n        <input type=\"text\"/><br/>\n\n        <button> Submit </button>\n\n        </p>\n\n        </>\n    )\n}\n\nexport default Register;\n\napp.jsx\nimport { useState } from 'react'\nimport heroImg from './assets/hero.png'","i":[]},{"p":115,"t":"import reactLogo from './assets/react.svg'\nimport viteLogo from './assets/vite.svg'\nimport './App.css'\nimport{\n  BrowserRouter as Router,\n  Routes,\n  Route,\n  Link\n} from \"react-router-dom\"\nimport Home from './home';\nimport Aboutus from './aboutus'\nimport Contact from './contact'\nimport Register from './register'\n\nfunction App() {\n  return(\n    <>\n    <Router>\n      <nav>\n        <Link to=\"/\"> Home </Link>{\"|\"}\n        <Link to=\"/aboutus\">About us </Link>{\"|\"}\n        <Link to=\"/contact\"> Contact </Link>{\"|\"}\n        <Link to=\"/register\"> Register </Link>{\"|\"}\n      </nav>\n\n         <Routes>\n           <Route path=\"/\" element={<Home/>}/>\n           <Route path=\"/aboutus\" element={<Aboutus/>}/>\n           <Route path=\"/contact\" element={<Contact/>}/>\n           <Route path=\"/register\" element={<Register/>}/>\n         </Routes>\n\n        </Router>\n        </>\n    )\n}\n\nexport default App","i":[]},{"p":116,"t":"","i":[]}]},{"n":36,"title":"Redux and Dispatch","page":117,"pages":[{"p":117,"t":"Redux and Dispatch\nStore.jsx\nimport { createStore } from \"redux\";\n\n//initial value\nconst initialState={\n    count:0\n};\n\nfunction controlRedux(state=initialState,action){\n    switch(action.type){\n        case \"increment\":\n            return{\n                count:state.count+1\n            }\n\n         case \"decrement\":\n             return{\n                 count:state.count-1\n             }\n\n         default: return state;\n     }\n}\n\n//create redux store\nconst dataStore=createStore(controlRedux);\n\nexport default dataStore;\n\napp.jsx\nimport { useState } from 'react'\nimport heroImg from './assets/hero.png'\nimport reactLogo from './assets/react.svg'\nimport viteLogo from './assets/vite.svg'\nimport './App.css'\nimport { useSelector, useDispatch } from 'react-redux'\n\nfunction App() {\n  const updateCounter=useSelector(\n    (state)=>state.count\n  );\n\n    const dispatch=useDispatch()","i":[]},{"p":118,"t":"  return(\n    <>\n    <h1>Counter:{updateCounter}</h1>\n    <button\nonClick={()=>dispatch({type:\"increment\"})}>Increment</button>\n    <button\nonClick={()=>dispatch({type:\"decrement\"})}>Decrement</button>\n    </>\n  );\n}\n\nexport default App","i":[]}]}];